     4	
     5		private NumVarStatMod odDecayMod;
     6	
     7		public OverdriveBuildDecayDown()
     8		{
     9			ID = staticID;
    10			category = Category.Misc;
    11			odDecayMod = new NumVarStatMod(ID, 0f, 10, VarStatModType.Override);
    12		}
    13	
    14		public override void Activate()
    15		{
    16			SetModStatus(givenStatus: true);
    17		}
    18	
    19		public override void Deactivate()
    20		{
    21			SetModStatus(givenStatus: false);
    22		}
    23	
    24		private void SetModStatus(bool givenStatus)
    25		{
    26			if (SetParentAsPlayer())
    27			{
    28				parentPlayer.overdriveBuildDecayRate.Modify(odDecayMod, givenStatus);
    29			}
    30		}
    31	}
